{
 "path": "programs/task-64074e8b.py",
 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    bg=max(set(v for r in g for v in r),key=lambda c:sum(r.count(c) for r in g))
    for y0 in range(h):
      for y1 in range(y0+2,h):
       for x0 in range(w):
        for x1 in range(x0+2,w):
         c=g[y0][x0]
         if c==bg: continue
         if any(g[y0][x]!=c or g[y1][x]!=c for x in range(x0,x1+1)): continue
         if any(g[y][x0]!=c or g[y][x1]!=c for y in range(y0,y1+1)): continue
         if any(g[y][x]!=bg for y in range(y0+1,y1) for x in range(x0+1,x1)): continue
         area=(y1-y0-1)*(x1-x0-1)
         fill=7 if area%2 else 2
         for y in range(y0+1,y1):
          for x in range(x0+1,x1): g[y][x]=fill
    return g
"
}

